from base import *
t=lambda txt,c=1,extra="":f'<div class="tile" style="grid-column:span {c};background:#000;font-size:12px;{extra}">{txt}</div>'
inner='<div style="display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:118px;gap:8px">'+t("<span class='q'>TIMER</span><div style='font-size:18px;margin-top:10px'>5:00</div>")+t("<span class='q'>NOW PLAYING</span><div style='margin-top:10px'><b>Song Title</b><br><span class='s'>Artist</span></div>")+t("<div style='display:flex;justify-content:space-between'><span class='q'>✎ NOTE</span><span class='q'>⧉ copy</span></div><div style='margin-top:8px;line-height:1.6;font-size:13px'>call Sam back 555-0142<br>brew upgrade --cask<span style=\"display:inline-block;width:1.5px;height:14px;background:#fff;vertical-align:middle;margin-left:1px\"></span></div>",2,"border-color:rgba(255,255,255,.3)")+'</div>'
body=cap("Open notch · Home with a Quick Note widget (medium), typing")+opened(inner,h=180)
body+=cap("Small size shows the first line · drag it onto the Shelf as text")+'<div class="row"><div class="tile" style="background:#000;width:130px;height:104px;font-size:12px"><span class="q">✎ NOTE</span><div style="margin-top:10px">call Sam back…</div><div class="q" style="margin-top:14px;font-size:11px">click to edit</div></div></div>'
open("m12.html","w").write(page("Home: a Quick Note widget","Jot something down without leaving what you’re doing.",body))
